        placed=False
        for g in cl:
            r=g[0]; m=(T[a]>=0)&(T[r]>=0); h=np.bincount(T[a][m]^T[r][m],minlength=8)
            if h.max()/h.sum()>=0.8:
                g.append(a); placed=True; break
        if not placed: cl.append([a])
    print('skill',s,'xor classes',cl)
